local L = ProjectEbonhold.L
-- ==============================================================================
-- Demonic Portal pins (owner, 2026-11-20: a player found one portal in three days).
--
-- A player who comes within 60 yards of a waiting portal is told by the server (a notice and a
-- sound, TormentChampionMgr::OnPortalNoticed) and gets SEND_TORMENT_PORTAL_SEEN: this module
-- remembers that portal for the character and pins it on the world map, zone maps only. While
-- the portal is closed (someone opened it, until it comes back) its pin is hidden: the server
-- sends the closed portals of the player's map on every map change (SEND_TORMENT_PORTALS, per
-- layer) and pushes each change to the map (SEND_TORMENT_PORTAL_STATE). Who fights at a portal forgets it
-- (SEND_TORMENT_PORTAL_USED): its pin comes back only when he comes near it again.
-- Positions: modules/torment/PortalData.lua, generated by tools/torment/export_portals.py (same
-- keying as modules/graveyards: GetCurrentMapAreaID() = WorldMapArea id + 1). Only spawn ids
-- travel. Found portals: ProjectEbonholdDB.portalsFound["<realm>-<name>"][spawnId] = true.
-- The world map's filter button can hide them (modules/checkpoint/map_filters.lua, "demonicPortals").
-- ==============================================================================
ProjectEbonhold = ProjectEbonhold or {}
local PP = {}
ProjectEbonhold.PortalPins = PP

-- The Torment frame's portal icon (hardmode.lua, "Demonic Portals" section).
local ICON = "Interface\\Icons\\Spell_Shadow_SummonFelGuard"
local WORLD_PIN_SIZE = 26   -- the ring; the icon disc inside is ~22 (the graveyard skull is 24)

local closed = {}      -- [spawnId] = GetTime() at which it is open again at the latest (server ceiling)
local closedMap = nil  -- map id the closed / open list is for
local open = nil       -- [spawnId] = true: the spots of closedMap where a portal waits now (nil = the server sent a closed list)

local tooltip = CreateFrame("GameTooltip", "ProjectEbonholdPortalTooltip", nil, "GameTooltipTemplate")
tooltip:SetFrameStrata("TOOLTIP")
tooltip:SetClampedToScreen(true)

local function CharKey()
    return (GetRealmName() or "?") .. "-" .. (UnitName("player") or "?")
end

local function Found()
    ProjectEbonholdDB = ProjectEbonholdDB or {}
    ProjectEbonholdDB.portalsFound = ProjectEbonholdDB.portalsFound or {}
    local key = CharKey()
    ProjectEbonholdDB.portalsFound[key] = ProjectEbonholdDB.portalsFound[key] or {}
    return ProjectEbonholdDB.portalsFound[key]
end

local function IsClosed(id)
    local untilTime = closed[id]
    if not untilTime then return false end
    if GetTime() >= untilTime then
        closed[id] = nil
        return false
    end
    return true
end

local function ShowTooltip(pin)
    tooltip:SetOwner(pin, "ANCHOR_CURSOR_RIGHT")
    tooltip:ClearLines()
    tooltip:AddLine(L["Demonic Portal"], 1, 0.82, 0)
    tooltip:AddLine(L["Talk to it and offer half of your life to open it: your group is pulled in and must survive the horde for 45 seconds. Each survivor opens a cache."], 1, 1, 1, true)
    tooltip:AddLine(L["Hidden from the map while it is closed."], 0.7, 0.7, 0.7, true)
    tooltip:Show()
end

-- Round pin (owner, 2026-11-21: the square icon read badly, then "use the skill tree's border"): the
-- icon cut to a disc (SetPortraitToTexture) inside the skill tree's gold ring (assets/class_ring.tga,
-- 256 px, the ring spans 84-100% of it), with the skill tree node's proportions: ring = icon x 1.16.
local RING = "Interface\\AddOns\\ProjectEbonhold\\assets\\class_ring"
local RING_COORDS = { 0, 1, 0, 1 }
local ICON_RATIO = 1 / 1.16

local function MakePin(parent, size)
    local pin = CreateFrame("Button", nil, parent)
    pin:SetSize(size, size)
    pin:EnableMouse(true)
    local disc = math.floor(size * ICON_RATIO + 0.5)
    pin.icon = pin:CreateTexture(nil, "ARTWORK")
    pin.icon:SetSize(disc, disc)
    pin.icon:SetPoint("CENTER")
    SetPortraitToTexture(pin.icon, ICON)
    pin.ring = pin:CreateTexture(nil, "OVERLAY")
    pin.ring:SetAllPoints(pin)
    pin.ring:SetTexture(RING)
    pin.ring:SetTexCoord(unpack(RING_COORDS))
    pin.highlight = pin:CreateTexture(nil, "HIGHLIGHT")
    pin.highlight:SetSize(disc, disc)
    pin.highlight:SetPoint("CENTER")
    SetPortraitToTexture(pin.highlight, ICON)
    pin.highlight:SetBlendMode("ADD")
    pin.highlight:SetAlpha(0.4)
    pin:SetScript("OnEnter", ShowTooltip)
    pin:SetScript("OnLeave", function() tooltip:Hide() end)
    return pin
end

-- World coordinates -> fraction of the zone map (x north, y west; rect left > right, top > bottom).
local function ToMapFraction(rect, worldX, worldY)
    local fx = (rect.left - worldY) / (rect.left - rect.right)
    local fy = (rect.top - worldX) / (rect.top - rect.bottom)
    return fx, fy
end

-- ------------------------------------------------------------------ world map
local worldPins = {}

local function HideWorldPins(from)
    for i = from, #worldPins do worldPins[i]:Hide() end
end

function PP.RefreshWorldMap()
    -- IsVisible: the detail frame stays "shown" with the map closed (see checkpoint.lua)
    if not WorldMapDetailFrame or not WorldMapDetailFrame:IsVisible() then
        HideWorldPins(1)
        return
    end
    local filters = ProjectEbonhold.MapFilters
    if filters and not filters.IsShown("demonicPortals") then
        HideWorldPins(1)
        return
    end
    local data = ProjectEbonhold.PortalData
    local mapId = GetCurrentMapAreaID and GetCurrentMapAreaID() or 0
    local zone = data and data[mapId]
    if not zone then
        HideWorldPins(1)
        return
    end

    local found = Found()
    local frame = WorldMapDetailFrame
    local parent = WorldMapButton or frame
    local width, height = frame:GetWidth(), frame:GetHeight()
    local count = 0
    for _, portal in ipairs(zone.portals) do
        -- The closed list only knows the map the player stands on: another continent's pins always show.
        local hidden = closedMap == zone.map and (IsClosed(portal.id) or (open ~= nil and not open[portal.id]))
        if found[portal.id] and not hidden then
            local fx, fy = ToMapFraction(zone, portal.x, portal.y)
            if fx >= 0 and fx <= 1 and fy >= 0 and fy <= 1 then
                count = count + 1
                local pin = worldPins[count]
                if not pin then
                    pin = MakePin(parent, WORLD_PIN_SIZE)
                    pin:SetFrameStrata("FULLSCREEN_DIALOG")
                    pin:SetToplevel(true)
                    worldPins[count] = pin
                end
                pin:SetParent(parent)
                pin:SetFrameLevel(frame:GetFrameLevel() + 15)
                pin:ClearAllPoints()
                pin:SetPoint("CENTER", frame, "TOPLEFT", fx * width, -fy * height)
                pin:Show()
            end
        end
    end
    HideWorldPins(count + 1)
end

-- ------------------------------------------------------------------ server
local function ParseEntry(entry)
    local id, secs = entry:match("^(%d+):(%d+)$")
    return tonumber(id), tonumber(secs)
end

-- Since 2026-11-23 a portal has up to 12 spots over its zone and waits at one: the server sends the OPEN spots of my map
-- ("<mapId>|open|<id>,<id>,..."), a found pin shows only if its spot is in it. The older closed list ("<mapId>|<id>:<s>,...")
-- is still read, for a server that sends it.
ProjectEbonhold.onEventReceived(ProjectEbonhold.SS.SEND_TORMENT_PORTALS, function(body)
    local mapId, list = (body or ""):match("^(%d+)|(.*)$")
    closed = {}
    open = nil
    closedMap = tonumber(mapId)
    local ids = (list or ""):match("^open|(.*)$")
    if ids then
        open = {}
        for id in ids:gmatch("%d+") do open[tonumber(id)] = true end
    else
        for entry in (list or ""):gmatch("[^,]+") do
            local id, secs = ParseEntry(entry)
            if id and secs and secs > 0 then closed[id] = GetTime() + secs end
        end
    end
    PP.RefreshWorldMap()
end)

-- One or more "<id>:<seconds closed, 0 = open>" (a portal that moved: its old spot shut, its new one open).
ProjectEbonhold.onEventReceived(ProjectEbonhold.SS.SEND_TORMENT_PORTAL_STATE, function(body)
    local mapId, entries = (body or ""):match("^(%d+)|(.*)$")
    if tonumber(mapId) ~= closedMap then return end
    for entry in (entries or ""):gmatch("[^,]+") do
        local id, secs = ParseEntry(entry)
        if id then
            local shut = secs and secs > 0
            closed[id] = shut and (GetTime() + secs) or nil
            if open then open[id] = (not shut) or nil end
        end
    end
    PP.RefreshWorldMap()
end)

ProjectEbonhold.onEventReceived(ProjectEbonhold.SS.SEND_TORMENT_PORTAL_SEEN, function(body)
    local id = tonumber((body or ""):match("^%d+|(%d+)$"))
    if not id then return end
    Found()[id] = true
    closed[id] = nil
    if open then open[id] = true end   -- I see it standing: it is open, whatever the last list said
    PP.RefreshWorldMap()
end)

-- Fought at it (owner, 2026-11-21: once opened and left, its marker goes): forgotten until I come near it again (SEEN).
ProjectEbonhold.onEventReceived(ProjectEbonhold.SS.SEND_TORMENT_PORTAL_USED, function(body)
    local id = tonumber((body or ""):match("^%d+|(%d+)$"))
    if not id then return end
    Found()[id] = nil
    PP.RefreshWorldMap()
end)

-- ------------------------------------------------------------------ events
local eventFrame = CreateFrame("Frame")
eventFrame:RegisterEvent("WORLD_MAP_UPDATE")
eventFrame:RegisterEvent("PLAYER_LOGIN")
eventFrame:SetScript("OnEvent", function(_, event)
    if event == "PLAYER_LOGIN" then
        -- After a /reload the server sent nothing new: ask for the closed list of this map.
        ProjectEbonhold.sendToServer(ProjectEbonhold.CS.REQUEST_TORMENT_PORTALS, "")
        return
    end
    PP.RefreshWorldMap()
end)

if WorldMapDetailFrame then
    WorldMapDetailFrame:HookScript("OnShow", PP.RefreshWorldMap)
    WorldMapDetailFrame:HookScript("OnHide", function()
        tooltip:Hide()
        HideWorldPins(1)
    end)
end

if ProjectEbonhold.MapFilters then
    ProjectEbonhold.MapFilters.OnChanged(function() PP.RefreshWorldMap() end)
end
